package org.dbsp.sqlCompiler.compiler.frontend.calciteCompiler;

import org.apache.calcite.sql.SqlNode;
import javax.annotation.Nullable;

/** A SQL statement obtained after parsing.  Some statements are not
 * <code>visible</code> because they are generated by the compiler internally.
 * These are not supposed to ever show up in error messages, for example. */
public record ParsedStatement(SqlNode statement, boolean visible, @Nullable String generatedSource) {
    public ParsedStatement(SqlNode statement, boolean visible) {
        this(statement, visible, null);
    }

    /** Preserve the actual parser input for generated statements, whose coordinates
     * do not refer to the user program. Rewrites retain this source unchanged. */
    public ParsedStatement withStatement(SqlNode replacement) {
        return new ParsedStatement(replacement, this.visible, this.generatedSource);
    }

    @Override
    public String toString() {
        try {
            return this.statement.toString();
        } catch (Exception e) {
            // This can happen if the statement is syntactically incorrect
            // See https://issues.apache.org/jira/browse/CALCITE-6708
            return this.statement.getKind().toString();
        }
    }
}
